const request = require('request');

const options = {
  method: 'POST',
  url: 'http://localhost:8080/rest/v1.1/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/viewer_documents',
  qs: {
    combined_xfdf: 'SOME_BOOLEAN_VALUE',
    markup_context: 'SOME_STRING_VALUE',
    pin_origin: 'SOME_STRING_VALUE',
    layer_type: 'SOME_STRING_VALUE'
  },
  headers: {'content-type': 'application/json'},
  body: {
    item_id: 'string',
    item_type: 'string',
    attachment_id: 'string',
    attachment_source: 'string',
    internal_pdm_tool_data: {
      file_key: 'string',
      file_format: 'string',
      file_locked: true,
      document_container_id: 'string',
      position_within_container: 'string'
    }
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("http://localhost:8080/rest/v1.1/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/viewer_documents?combined_xfdf=SOME_BOOLEAN_VALUE&markup_context=SOME_STRING_VALUE&pin_origin=SOME_STRING_VALUE&layer_type=SOME_STRING_VALUE"),
    Content = new StringContent("{\"item_id\":\"string\",\"item_type\":\"string\",\"attachment_id\":\"string\",\"attachment_source\":\"string\",\"internal_pdm_tool_data\":{\"file_key\":\"string\",\"file_format\":\"string\",\"file_locked\":true,\"document_container_id\":\"string\",\"position_within_container\":\"string\"}}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
